sfx.__fn:
function sfx(kind, opt){
    if(!A.ctx || !SFX[kind]) return;
    const t = A.ctx.currentTime;
    if(kind === 'hit'){ if(t - lastHitT < 0.045) return; lastHitT = t; }
    try { SFX[kind](A.ctx, A.g, t + 0.005, opt); } catch(e){}
  }

volumes.__fn:
function volumes(){
    if(!A.g) return; const o = typeof OPT !== 'undefined' ? OPT : {}, now = A.ctx.currentTime;
    const curve = x => Math.pow(Math.max(0, Math.min(100, x ?? 70)) / 100, 1.6);
    A.g.master.gain.setTargetAtTime(curve(o.vol ?? 80), now, 0.05);
    A.g.music.gain.setTargetAtTime(curve(o.music ?? 60) * 1.0, now, 0.05);
    A.g.sfx.gain.setTargetAtTime(curve(o.sfx ?? 80) * 1.1, now, 0.05);
  }

renderSong.__fn:
async function renderSong(name, secs, sr = 44100){
    const song = SONGS[name], ctx = new OfflineAudioContext(2, Math.ceil(sr * secs), sr), g = graph(ctx, ctx.destination);
    g.master.gain.value = 1; g.music.gain.value = 1; setDelayTime(g, song);
    const bus = songBus(ctx, g), bs = compile(song); let t = 0.05, i = 0;
    while(t < secs){ t += scheduleBar(bus, song, bs[i], t); i++; if(i >= bs.length) i = song.loopBar || 0; }
    return ctx.startRendering();
  }

renderSfx.__fn:
async function renderSfx(list, sr = 44100){              // [[kind, opt, time], ...]
    const end = Math.max(...list.map(x => x[2])) + 1.2, ctx = new OfflineAudioContext(2, Math.ceil(sr * end), sr), g = graph(ctx, ctx.destination);
    g.master.gain.value = 1; g.sfx.gain.value = 1;
    for(const [k, o, t] of list){ if(k === 'hit') last.hitE = last.hitH = undefined; SFX[k](ctx, g, t, o); }
    return ctx.startRendering();
  }

compile.__fn:
function compile(song){
    if(song._bars) return song._bars;
    const spBar = song.beats * song.spb, out = [];
    for(const sec of song.form){
      const ph = song.ph[sec.p], on = new Set((sec.on || '').split(/\s+/));
      const chordBars = bars(ph.ch), melBars = ph.m ? bars(ph.m) : null;
      const mres = song.mres || 1, bres = song.bres || mres, ares = song.ares || mres;
      const melInst = sec.m || song.inst.mel, mo = sec.mo || 0;
      for(let bi = 0; bi < chordBars.length; bi++){
        const ev = [], cs = chordBars[bi], seg = spBar / cs.length;
        const chordAt = step => chordTones(song, cs[Math.min(cs.length - 1, Math.floor(step / seg))]);
        const nextChord = chordTones(song, (chordBars[bi + 1] || chordBars[0])[0]);
        const push = (track, inst, step, note, dur, vel) => ev.push({track, inst, step, note, dur, vel});
        // Flächen: Akkord pro Abschnitt
        if(on.has('pad') || on.has('ch')) cs.forEach((tok, k) => {
          const ch = chordTones(song, tok);
          const base = song.root + 12 + ch.root;
          ch.tones.forEach(tn => { let n = base + tn; while(n > song.root + 24) n -= 12; while(n < song.root + 10) n += 12;
            if(on.has('pad')) push('pad', song.inst.pad || 'pad', k * seg, n, seg, 1);
            if(on.has('ch')) push('ch', 'choir', k * seg, n, seg, 1); });
        });
        // Bass
        if(on.has('bass')){
          const pat = bars(song.pat.bass[sec.b || 'a'])[0];
          pat.forEach((tok, k) => { if(tok === '.' || tok === '-') return;
            let len = 1; while(pat[k + len] === '-') len++;
            const step = k * bres, ch = chordAt(step), r = song.root + ch.root + (song.bassOct ?? -12);
            const n = tok === 'R' ? r : tok === 'F' ? r + ch.tones[2] : tok === 'T' ? r + ch.tones[1] : tok === 'O' ? r + 12
              : tok === 'L' ? r + ch.tones[2] - 12 : tok === 'A' ? song.root + nextChord.root + (song.bassOct ?? -12) - 1 : r;
            push('bass', song.inst.bass || 'bass', step, n, len * bres, k === 0 ? 1 : 0.85); });
        }
        // Akkord-Tupfer
        if(on.has('stab')){
          const pat = bars(song.pat.stab[sec.s || 'a'])[0];
          pat.forEach((tok, k) => { if(tok !== 'S') return; const step = k * (song.sres || mres), ch = chordAt(step);
            ch.tones.forEach(tn => { let n = song.root + 12 + ch.root + tn; while(n > song.root + 26) n -= 12; push('stab', song.inst.stab, step, n, song.sres || mres, 0.8); }); });
        }
        // Arpeggio
        if(on.has('arp')){
          const pat = bars(song.pat.arp[sec.a || 'a'])[0];
          pat.forEach((tok, k) => { if(tok === '.' || tok === '-') return; const step = k * ares, ch = chordAt(step);
            const idx = {1: 0, 3: 1, 5: 2, 8: 3, 7: 4}[tok] ?? 0;
            const n = song.root + 24 + ch.root + (idx === 3 ? 12 : idx === 4 ? (ch.tones[3] || 10) : ch.tones[idx]) + (song.arpOct || 0);
            push('arp', sec.ai || song.inst.arp, step, n, ares * 2, k % 2 ? 0.7 : 0.9); });
        }
        // Melodie (+ Verdopplung)
        if(melBars && (on.has('mel') || on.has('cm'))){
          const mb = melBars[bi] || [];
          mb.forEach((tok, k) => { if(tok === '.' || tok === '-') return; const d = deg(song, tok); if(d == null) return;
            let len = 1; while(mb[k + len] === '-') len++;
            if(k + len >= mb.length){ let j = bi + 1;          // Haltebogen über den Taktstrich
              while(melBars[j]){ let q = 0; while(q < melBars[j].length && melBars[j][q] === '-') q++; len += q; if(q < melBars[j].length) break; j++; } }
            const n = song.mb + d + mo, vel = k === 0 ? 1 : 0.88;
            if(on.has('mel')) push('mel', melInst, k * mres, n, len * mres, vel);
            if(on.has('cm')) push('cm', sec.cm || song.inst.cm, k * mres, n + (sec.co ?? -12), len * mres, vel * 0.8); });
        }
        // Schlagzeug
        if(on.has('drum')){
          const kit = song.pat.drum[sec.d || 'a'];
          for(const [inst, str] of Object.entries(kit)){
            const s = str.replace(/\s/g, '');
            for(let k = 0; k < s.length; k++){ const ch = s[k]; if(ch === '.') continue; push('drum', inst, k * spBar / s.length, 0, 1, ch === 'X' ? 1 : ch === 'x' ? 0.75 : 0.45); }
          }
        }
        out.push({ev, v: sec.v || 1});
      }
    }
    song._bars = out;
    return out;
  }

