  e.cds = e.cds || {}; for(const k in e.cds) if(e.cds[k] > 0) e.cds[k]--;
  let opts = (e.moves || []).filter(m => moveOK(e, m));
  if(!opts.length) opts = (e.moves || []).filter(m => m.dmg) || e.moves;
  const w = m => { let x = m.w || 1; if(e.lastName === m.name) x *= m.dmg ? .6 : .25;
