  if(pickM.cd) e.cds[pickM.name] = pickM.cd + 1;
  const it = {};
  for(const [k, v] of Object.entries(pickM)) if(!['w','if','cd','minTier','up'].includes(k)) it[k] = v;
  (pickM.up || []).slice(0, biomeTier()).forEach(u => { for(const [k, v] of Object.entries(u)){
    if(typeof v === 'number'){ if(k === 'dmg' && !it.dmg) continue; if(k === 'heal'){ ['healLow','healAllies','healSelf'].forEach(h => { if(it[h]) it[h] += v; }); continue; } it[k] = (it[k] || 0) + v; } else it[k] = v; } });
  return it;
}

